def run_menu(events, paths):
    """events: list of dicts. paths: list of (name, condition, prescale), where condition(event) -> bool.
    A path keeps the 1st, (N+1)th, (2N+1)th, ... of the events satisfying its condition (N = prescale).
    An event is accepted if any path keeps it. Return (accepted event indices in order, {name: kept count})."""
    accepted = [i for i, e in enumerate(events) if any(cond(e) for _, cond, _ in paths)]
    return accepted, {name: sum(cond(e) for e in events) for name, cond, _ in paths}

